CREATE FUNCTION "current_manager"(dept_id character(4)) RETURNS character varying(32) LANGUAGE plpgsql STABLE AS $body$
DECLARE
  max_date date;
BEGIN
  max_date := (SELECT MAX("from_date") FROM "dept_manager" WHERE "dept_no" = dept_id);
  PERFORM set_config('megasamples.max_date', (max_date)::text, false);
  RETURN (SELECT EMP_NAME("emp_no") FROM "dept_manager" WHERE "dept_no" = dept_id AND "from_date" = max_date LIMIT 1);
END $body$;

CREATE FUNCTION "emp_dept_id"(employee_id integer) RETURNS character(4) LANGUAGE plpgsql STABLE AS $body$
DECLARE
  max_date date;
BEGIN
  max_date := (SELECT MAX("from_date") FROM "dept_emp" WHERE "emp_no" = employee_id);
  PERFORM set_config('megasamples.max_date', (max_date)::text, false);
  RETURN (SELECT "dept_no" FROM "dept_emp" WHERE "emp_no" = employee_id AND "from_date" = max_date LIMIT 1);
END $body$;

CREATE FUNCTION "emp_dept_name"(employee_id integer) RETURNS character varying(40) LANGUAGE plpgsql STABLE AS $body$
BEGIN
  RETURN (SELECT "dept_name" FROM "departments" WHERE "dept_no" = EMP_DEPT_ID(employee_id));
END $body$;

CREATE FUNCTION "emp_name"(employee_id integer) RETURNS character varying(32) LANGUAGE plpgsql STABLE AS $body$
BEGIN
  RETURN (SELECT "first_name" || ' ' || "last_name" AS name FROM "employees" WHERE "emp_no" = employee_id);
END $body$;

CREATE FUNCTION "employees_usage"() RETURNS text LANGUAGE plpgsql VOLATILE AS $body$
BEGIN
  RETURN '
    == USAGE ==
    ====================

    PROCEDURE show_departments()

        shows the departments with the manager and
        number of employees per department

    FUNCTION current_manager (dept_id)

        Shows who is the manager of a given departmennt

    FUNCTION emp_name (emp_id)

        Shows name and surname of a given employee

    FUNCTION emp_dept_id (emp_id)

        Shows the current department of given employee
';
END $body$;

CREATE FUNCTION "employees_help"() RETURNS TABLE("info" text) LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  RETURN QUERY SELECT EMPLOYEES_USAGE() AS info;
END $body$;

CREATE FUNCTION "show_departments"() RETURNS TABLE("dept_no" character(4), "dept_name" character varying(40), "manager" character varying, "count" bigint) LANGUAGE plpgsql AS $body$
#variable_conflict use_column
BEGIN
  DROP TABLE IF EXISTS department_max_date;
  DROP TABLE IF EXISTS department_people;
  CREATE TEMP TABLE department_max_date (emp_no integer NOT NULL PRIMARY KEY, dept_from_date date NOT NULL, dept_to_date date NOT NULL);
  CREATE INDEX department_max_date_key1 ON department_max_date (dept_from_date, dept_to_date);
  INSERT INTO department_max_date SELECT "emp_no", MAX("from_date"), MAX("to_date") FROM "dept_emp" GROUP BY "emp_no";
  CREATE TEMP TABLE department_people (emp_no integer NOT NULL, dept_no character(4) NOT NULL, PRIMARY KEY (emp_no, dept_no));
  INSERT INTO department_people SELECT dmd."emp_no", "dept_no" FROM department_max_date AS dmd INNER JOIN "dept_emp" AS de ON dmd.dept_from_date = de."from_date" AND dmd.dept_to_date = de."to_date" AND dmd."emp_no" = de."emp_no";
  RETURN QUERY SELECT "dept_no", "dept_name", "manager", COUNT(*) FROM "v_full_departments" INNER JOIN department_people USING (dept_no) GROUP BY "dept_no", "dept_name", "manager";
  DROP TABLE department_max_date;
  DROP TABLE department_people;
END $body$;

CREATE VIEW "dept_emp_latest_date" ("emp_no", "from_date", "to_date") AS
SELECT "dept_emp"."emp_no" AS "emp_no", MAX("dept_emp"."from_date") AS "from_date", MAX("dept_emp"."to_date") AS "to_date" FROM "dept_emp" GROUP BY "dept_emp"."emp_no";

CREATE VIEW "current_dept_emp" ("emp_no", "dept_no", "from_date", "to_date") AS
SELECT "l"."emp_no" AS "emp_no", "d"."dept_no" AS "dept_no", "l"."from_date" AS "from_date", "l"."to_date" AS "to_date" FROM ("dept_emp" AS "d" JOIN "dept_emp_latest_date" AS "l" ON ((("d"."emp_no" = "l"."emp_no") AND ("d"."from_date" = "l"."from_date") AND ("l"."to_date" = "d"."to_date"))));

CREATE VIEW "v_full_departments" ("dept_no", "dept_name", "manager") AS
SELECT "departments"."dept_no" AS "dept_no", "departments"."dept_name" AS "dept_name", CURRENT_MANAGER("departments"."dept_no") AS "manager" FROM "departments";

CREATE VIEW "v_full_employees" ("emp_no", "first_name", "last_name", "birth_date", "gender", "hire_date", "department") AS
SELECT "employees"."emp_no" AS "emp_no", "employees"."first_name" AS "first_name", "employees"."last_name" AS "last_name", "employees"."birth_date" AS "birth_date", "employees"."gender" AS "gender", "employees"."hire_date" AS "hire_date", EMP_DEPT_NAME("employees"."emp_no") AS "department" FROM "employees";
